import { test, expect } from "@playwright/test";

test.describe("接口契约、边界条件与安全异常校验", () => {
  test("GET /api/posts 应支持默认加载、频道筛选、游标分页与非法参数精确报错", async ({ request }) => {
    const defaultRes = await request.get("/api/posts");
    expect(defaultRes.status()).toBe(200);
    const defaultBody = await defaultRes.json();
    expect(Array.isArray(defaultBody.items)).toBe(true);
    expect("nextCursor" in defaultBody).toBe(true);

    const page1Res = await request.get("/api/posts?tab=for_you&limit=2");
    expect(page1Res.status()).toBe(200);
    const page1Body = await page1Res.json();
    expect(page1Body.items.length).toBeLessThanOrEqual(2);

    if (page1Body.nextCursor) {
      const page2Res = await request.get(`/api/posts?tab=for_you&limit=2&cursor=${encodeURIComponent(page1Body.nextCursor)}`);
      expect(page2Res.status()).toBe(200);
      const page2Body = await page2Res.json();
      const page1Ids = new Set(page1Body.items.map((item: { id: string }) => item.id));
      for (const item of page2Body.items) {
        expect(page1Ids.has(item.id)).toBe(false);
      }
    }

    const filteredRes = await request.get("/api/posts?tab=following&limit=5");
    expect(filteredRes.status()).toBe(200);
    const filteredBody = await filteredRes.json();
    expect(Array.isArray(filteredBody.items)).toBe(true);
    expect(filteredBody.items.length).toBeLessThanOrEqual(5);

    const invalidTabRes = await request.get("/api/posts?tab=invalid_tab&limit=-1");
    expect(invalidTabRes.status()).toBe(400);
    expect(JSON.stringify(await invalidTabRes.json())).toContain("400_INVALID_QUERY");

    const zeroLimitRes = await request.get("/api/posts?limit=0");
    expect(zeroLimitRes.status()).toBe(400);
    expect(JSON.stringify(await zeroLimitRes.json())).toContain("400_INVALID_QUERY");
  });

  test("POST /api/posts 应校验内容非空、字数上限精确错误码并成功发布动态", async ({ request }) => {
    const emptyRes = await request.post("/api/posts", {
      data: { content: "   " }
    });
    expect(emptyRes.status()).toBe(400);
    expect(JSON.stringify(await emptyRes.json())).toContain("400_CONTENT_EMPTY");

    const tooLongContent = "超长边界测试文本".repeat(100);
    const tooLongRes = await request.post("/api/posts", {
      data: { content: tooLongContent }
    });
    expect(tooLongRes.status()).toBe(400);
    expect(JSON.stringify(await tooLongRes.json())).toContain("400_CONTENT_TOO_LONG");

    const validContent = `自动化测试动态 ${Date.now()}`;
    const createRes = await request.post("/api/posts", {
      data: { content: validContent }
    });
    expect([200, 201]).toContain(createRes.status());
    const created = await createRes.json();
    expect(created.id).toBeTruthy();
    expect(created.content).toBe(validContent);
    expect(created.createdAt).toBeTruthy();
  });

  test("POST /api/posts/:id/interact 应支持多种互动往返切换与异常精确报错", async ({ request }) => {
    const createRes = await request.post("/api/posts", {
      data: { content: `互动状态翻转测试 ${Date.now()}` }
    });
    expect([200, 201]).toContain(createRes.status());
    const post = await createRes.json();

    const likeFirstRes = await request.post(`/api/posts/${post.id}/interact`, {
      data: { action: "like" }
    });
    expect(likeFirstRes.status()).toBe(200);
    const likeFirst = await likeFirstRes.json();
    expect(likeFirst.postId).toBe(post.id);
    expect(likeFirst.action).toBe("like");
    expect(typeof likeFirst.active).toBe("boolean");
    expect(likeFirst.count).toBeGreaterThanOrEqual(0);

    const likeSecondRes = await request.post(`/api/posts/${post.id}/interact`, {
      data: { action: "like" }
    });
    expect(likeSecondRes.status()).toBe(200);
    const likeSecond = await likeSecondRes.json();
    expect(likeSecond.active).toBe(!likeFirst.active);
    expect(likeSecond.count).toBeGreaterThanOrEqual(0);

    const repostRes = await request.post(`/api/posts/${post.id}/interact`, {
      data: { action: "repost" }
    });
    expect(repostRes.status()).toBe(200);

    const invalidActionRes = await request.post(`/api/posts/${post.id}/interact`, {
      data: { action: "invalid_action" }
    });
    expect(invalidActionRes.status()).toBe(400);
    expect(JSON.stringify(await invalidActionRes.json())).toContain("400_INVALID_ACTION");

    const notFoundRes = await request.post("/api/posts/non-existent-post-id-999999/interact", {
      data: { action: "bookmark" }
    });
    expect(notFoundRes.status()).toBe(404);
    expect(JSON.stringify(await notFoundRes.json())).toContain("404_POST_NOT_FOUND");
  });

  test("GET 与 PUT /api/preferences 应校验主题枚举与 reducedMotion 布尔类型", async ({ request }) => {
    const getRes = await request.get("/api/preferences");
    expect(getRes.status()).toBe(200);
    const currentPref = await getRes.json();
    expect(["light", "dim", "lights_out"]).toContain(currentPref.theme);
    expect(typeof currentPref.reducedMotion).toBe("boolean");

    const putRes = await request.put("/api/preferences", {
      data: { theme: "lights_out", reducedMotion: true }
    });
    expect(putRes.status()).toBe(200);
    const updatedPref = await putRes.json();
    expect(updatedPref.theme).toBe("lights_out");
    expect(updatedPref.reducedMotion).toBe(true);
    expect(updatedPref.updatedAt).toBeTruthy();

    const invalidThemeRes = await request.put("/api/preferences", {
      data: { theme: "neon_pink", reducedMotion: false }
    });
    expect(invalidThemeRes.status()).toBe(400);
    expect(JSON.stringify(await invalidThemeRes.json())).toContain("400_INVALID_PREFERENCE");

    const invalidMotionRes = await request.put("/api/preferences", {
      data: { theme: "dim", reducedMotion: "yes" }
    });
    expect(invalidMotionRes.status()).toBe(400);
    expect(JSON.stringify(await invalidMotionRes.json())).toContain("400_INVALID_PREFERENCE");
  });
});

test.describe("x.com 风格 UI、交互防重、竞态防护与错误恢复测试", () => {
  test("应支持频道切换并防止慢响应导致的异步竞态覆盖", async ({ page }) => {
    await page.goto("/");

    const forYouTab = page.getByRole("tab", { name: /For you|为你推荐/i });
    const followingTab = page.getByRole("tab", { name: /Following|正在关注/i });
    await expect(forYouTab).toBeVisible();
    await expect(followingTab).toBeVisible();

    await page.route("**/api/posts*tab=following*", async (route) => {
      await new Promise((resolve) => setTimeout(resolve, 600));
      await route.continue();
    });

    await followingTab.click();
    await forYouTab.click();

    await expect(forYouTab).toHaveAttribute("aria-selected", "true");
    await page.waitForTimeout(700);
    await expect(forYouTab).toHaveAttribute("aria-selected", "true");
  });

  test("发布框应拦截空白提交、防止慢网双击重复提交并支持键盘快捷键", async ({ page }) => {
    await page.goto("/");

    const composerInput = page.getByRole("textbox", { name: /What is happening|有什么新鲜事|发布动态/i });
    const postButton = page.getByRole("button", { name: /^Post$|^发布$/i });

    await expect(composerInput).toBeVisible();
    await composerInput.fill("   ");
    await expect(postButton).toBeDisabled();

    let postRequestCount = 0;
    await page.route("**/api/posts", async (route) => {
      if (route.request().method() === "POST") {
        postRequestCount += 1;
        await new Promise((resolve) => setTimeout(resolve, 400));
      }
      await route.continue();
    });

    const doubleClickText = `防重测试动态 ${Date.now()}`;
    await composerInput.fill(doubleClickText);
    await expect(postButton).toBeEnabled();

    await postButton.dblclick();
    await expect(page.getByText(doubleClickText)).toBeVisible();
    expect(postRequestCount).toBe(1);

    await page.unroute("**/api/posts");

    const shortcutText = `快捷键发布测试 ${Date.now()}`;
    await composerInput.fill(shortcutText);
    const shortcutPromise = page.waitForResponse(
      (res) => res.url().includes("/api/posts") && res.request().method() === "POST"
    );
    await composerInput.press("Control+Enter");
    const shortcutRes = await shortcutPromise;
    expect([200, 201]).toContain(shortcutRes.status());
    await expect(page.getByText(shortcutText)).toBeVisible();
  });

  test("发布包含 XSS 载荷的动态应以纯文本安全渲染且不执行脚本", async ({ page }) => {
    let dialogTriggered = false;
    page.on("dialog", async (dialog) => {
      dialogTriggered = true;
      await dialog.dismiss();
    });

    await page.goto("/");
    const xssPayload = `<img src=x onerror=alert(1)> 安全转义测试 ${Date.now()}`;
    const composerInput = page.getByRole("textbox", { name: /What is happening|有什么新鲜事|发布动态/i });
    const postButton = page.getByRole("button", { name: /^Post$|^发布$/i });

    await composerInput.fill(xssPayload);
    const createPromise = page.waitForResponse(
      (res) => res.url().includes("/api/posts") && res.request().method() === "POST"
    );
    await postButton.click();
    await createPromise;

    await expect(page.getByText(xssPayload)).toBeVisible();
    expect(dialogTriggered).toBe(false);
  });

  test("应支持点赞乐观更新与刷新持久化，并在接口失败时回滚状态", async ({ page }) => {
    await page.goto("/");

    const firstArticle = page.getByRole("article").first();
    await expect(firstArticle).toBeVisible();
    const likeButton = firstArticle.getByRole("button", { name: /Like|点赞/i });
    const initialPressed = await likeButton.getAttribute("aria-pressed");

    const interactPromise = page.waitForResponse(
      (res) => res.url().includes("/interact") && res.request().method() === "POST" && res.status() === 200
    );
    await likeButton.click();
    await interactPromise;

    const expectedPressed = initialPressed === "true" ? "false" : "true";
    await expect(likeButton).toHaveAttribute("aria-pressed", expectedPressed);

    await page.reload();
    const reloadedLikeButton = page.getByRole("article").first().getByRole("button", { name: /Like|点赞/i });
    await expect(reloadedLikeButton).toHaveAttribute("aria-pressed", expectedPressed);

    await page.route("**/api/posts/*/interact", async (route) => {
      await route.fulfill({
        status: 500,
        contentType: "application/json",
        body: JSON.stringify({ error: "500_INTERNAL_ERROR" })
      });
    });

    await reloadedLikeButton.click();
    await expect(reloadedLikeButton).toHaveAttribute("aria-pressed", expectedPressed);
  });

  test("信息流空状态与接口异常时应展示友好反馈且支持重试", async ({ page }) => {
    await page.route("**/api/posts*", async (route) => {
      if (route.request().method() === "GET") {
        await route.fulfill({
          status: 200,
          contentType: "application/json",
          body: JSON.stringify({ items: [], nextCursor: null })
        });
        return;
      }
      await route.continue();
    });

    await page.goto("/");
    await expect(page.getByText(/暂无动态|No posts|空空如也/i)).toBeVisible();
    await page.unroute("**/api/posts*");
  });

  test("应支持切换主题模式与动效降级偏好并在 DOM 与刷新后持久生效", async ({ page }) => {
    await page.goto("/");

    const themeToggleOrMenu = page.getByRole("button", { name: /Display|Appearance|主题|外观/i });
    await expect(themeToggleOrMenu).toBeVisible();
    await themeToggleOrMenu.click();

    const lightsOutOption = page.getByRole("radio", { name: /Lights out|熄灯|深黑/i });
    await expect(lightsOutOption).toBeVisible();

    const prefPromise = page.waitForResponse(
      (res) => res.url().includes("/api/preferences") && res.request().method() === "PUT" && res.status() === 200
    );
    await lightsOutOption.click();
    await prefPromise;

    await page.reload();
    const getPrefRes = await page.request.get("/api/preferences");
    expect(getPrefRes.status()).toBe(200);
    const prefData = await getPrefRes.json();
    expect(prefData.theme).toBe("lights_out");

    const rootThemeAttr = await page.evaluate(() => {
      return document.documentElement.getAttribute("data-theme") || document.body.getAttribute("data-theme") || document.documentElement.className;
    });
    expect(rootThemeAttr.toLowerCase()).toContain("lights");
  });
});
